pub(crate) fn oci_plugin_schema() -> PluginSchema {
    let container_fields = {
        let mut fields = HashMap::new();
        fields.insert(
            "name".to_string(),
            FieldSchema {
                field_type: FieldType::String,
                required: true,
                description: "Incus instance name (must match hostname inside container)".to_string(),
